import React, { useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';

// Actually, using a real short beep base64 string for a pleasant notification
const BEEP_SOUND = "data:audio/wav;base64,";

export function AudioNotifier() {
  const notifications = useSelector(state => state.notifications.data);
  const { currentUser } = useSelector(state => state.auth);
  const audioRef = useRef(null);
  const playedNotificationIds = useRef(new Set());
  
  // Set up the audio element once
  useEffect(() => {
    const audio = new Audio(BEEP_SOUND);
    audio.volume = 0.5;
    audioRef.current = audio;
  }, []);

  useEffect(() => {
    if (!currentUser) return;

    // Look for new ITEM_READY notifications that haven't been played
    // Make sure they belong to the current user OR are global role notifications
    const myNotifications = notifications.filter(n => n.userId === currentUser.id || n.role === currentUser.role);
    
    const newReadyNotifs = myNotifications.filter(
      n => n.type === 'ITEM_READY' && !n.isRead && !playedNotificationIds.current.has(n.id)
    );

    if (newReadyNotifs.length > 0) {
      newReadyNotifs.forEach(n => {
        playedNotificationIds.current.add(n.id);
      });
      
      // Play sound
      if (audioRef.current) {
        audioRef.current.play().catch(error => {
          // Gracefully handle autoplay restrictions
          // If the user hasn't interacted with the document yet, this will fail
          // That is expected and handled gracefully here.
          console.log("Audio autoplay prevented by browser. User interaction needed.", error);
        });
      }
    }
  }, [notifications, currentUser]);

  return null; // This component doesn't render anything visually
}
